async def process_bullmq_job(job, job_token):
    gen_id = job.data.get('generationId') or job.data.get('id') or (job.id if job else None)
    try:
        pass
    except Exception as e:
        log(f'[{WORKER_ID}] Could not get queue counts: {e}')
